H = PatternFill("solid", fgColor="0B2545"); HF = Font(bold=True, color="FFFFFF"); W = Alignment(wrap_text=True, vertical="top")


def spec_xlsx(fn, title, rows, note):
    wb = Workbook(); ws = wb.active; ws.title = "Спецификация"
    ws.append([title]); ws.cell(1, 1).font = Font(bold=True, size=12)
    ws.append([note]); ws.append([])
    ws.append(["№", "Наименование", "Характеристики / ГОСТ / ТУ", "Ед.", "Кол-во", "Цена за ед. с НДС, ₽", "Сумма с НДС, ₽", "Производитель / страна", "Номер реестровой записи (ПП 719 / ГИСП)", "Срок поставки", "Примечание"])
    for c in ws[4]: c.fill = H; c.font = HF; c.alignment = W
    for r in rows: ws.append(list(r) + [""] * 6)
    for i, w in enumerate([5, 48, 60, 8, 10, 14, 14, 22, 22, 14, 24], 1): ws.column_dimensions[CL(i)].width = w
    for row in ws.iter_rows(min_row=5):
        for c in row: c.alignment = W
    wb.save(OUT + fn); return fn


