def body(x):
    t = ["Добрый день!", "",
         "ООО «Гидропас» — поставщик химических реагентов, материалов и оборудования для предприятий энергетики, водоканалов и бюджетных организаций — просит направить коммерческое предложение:", ""]
    for b in x["blocks"]:
        if isinstance(b, tuple): t += [f"■ {b[0]}", f"   {b[1]}"]
        else: t.append(f"■ {b}")
    if x["att"]: t += ["", "Подробная спецификация — во вложении (" + ", ".join(x["att"]) + "); просим заполнить цены в ней."]
    t += ["", "В предложении просим указать:",
          "1) цену за единицу с НДС (и ставку НДС) — с доставкой до указанного города, а также на условиях самовывоза;",
          "2) производителя, страну происхождения и номер реестровой записи (ПП 719 / ГИСП), если есть;",
          "3) срок поставки, минимальную партию, упаковку;",
          "4) условия оплаты (базово — оплата по факту поставки, отсрочка до 7–10 рабочих дней);",
          "5) срок действия цены; документы качества (паспорт, сертификат/декларация, СГР при необходимости)."]
    if x["extra"]: t += ["", x["extra"]]
    t += ["", f"Ответ просим направить {x['due']}. Будем благодарны за оперативность.", "", "С уважением,", "Александр Орлов", "ООО «Гидропас»", "info@gidropas.ru"]
    return "\n".join(t)


